'use client';

// components/ThemeToggle.tsx
// Light / Dark / System switch in the dashboard header (DashboardShell).
// Default is Light. The choice is a per-browser convenience kept in
// localStorage; app/layout.tsx applies it before first paint (THEME_SCRIPT)
// so the page doesn't flash, and app/dark-theme.css (generated by
// scripts/generateDarkTheme.mjs) holds the dark colors for
// <html data-theme="dark">.

import { useEffect, useState } from 'react';
import { useLanguage } from '@/contexts/LanguageContext';

export type ThemeChoice = 'light' | 'dark' | 'system';
export const THEME_STORAGE_KEY = 'theme';

/** Runs inline in <head> before the page renders — keep it tiny and in
 *  step with applyTheme below. */
export const THEME_SCRIPT = `(function(){try{var c=localStorage.getItem('${THEME_STORAGE_KEY}');var d=c==='dark'||(c==='system'&&window.matchMedia('(prefers-color-scheme: dark)').matches);document.documentElement.setAttribute('data-theme',d?'dark':'light');}catch(e){}})();`;

function readChoice(): ThemeChoice {
  try {
    const v = localStorage.getItem(THEME_STORAGE_KEY);
    return v === 'dark' || v === 'system' ? v : 'light';
  } catch {
    return 'light';
  }
}

function applyTheme(choice: ThemeChoice) {
  const dark = choice === 'dark' || (choice === 'system' && window.matchMedia('(prefers-color-scheme: dark)').matches);
  document.documentElement.setAttribute('data-theme', dark ? 'dark' : 'light');
}

const NEXT: Record<ThemeChoice, ThemeChoice> = { light: 'dark', dark: 'system', system: 'light' };
const ICON: Record<ThemeChoice, string> = { light: '☀️', dark: '🌙', system: '🖥️' };
const LABEL: Record<ThemeChoice, { he: string; en: string }> = {
  light: { he: 'מצב בהיר', en: 'Light mode' },
  dark: { he: 'מצב כהה', en: 'Dark mode' },
  system: { he: 'לפי הגדרות המכשיר', en: 'Match device' },
};

export function ThemeToggle() {
  const { lang } = useLanguage();
  const [choice, setChoice] = useState<ThemeChoice>('light');

  useEffect(() => {
    const stored = readChoice();
    // eslint-disable-next-line react-hooks/set-state-in-effect -- localStorage is only readable after mount
    setChoice(stored);
    applyTheme(stored);
  }, []);

  // While on "system", follow the device switching between light and dark.
  useEffect(() => {
    if (choice !== 'system') return;
    const mq = window.matchMedia('(prefers-color-scheme: dark)');
    const onChange = () => applyTheme('system');
    mq.addEventListener('change', onChange);
    return () => mq.removeEventListener('change', onChange);
  }, [choice]);

  const cycle = () => {
    const next = NEXT[choice];
    setChoice(next);
    applyTheme(next);
    try {
      localStorage.setItem(THEME_STORAGE_KEY, next);
    } catch {
      // Private mode / blocked storage — the choice just won't persist.
    }
  };

  const nextLabel = LABEL[NEXT[choice]][lang];
  return (
    <button
      type="button"
      onClick={cycle}
      title={`${LABEL[choice][lang]} — ${lang === 'he' ? 'לחצו למעבר ל' : 'click for '}${nextLabel}`}
      aria-label={`${LABEL[choice][lang]}. ${lang === 'he' ? 'מעבר ל' : 'Switch to '}${nextLabel}`}
      className="flex h-8 w-8 items-center justify-center rounded-lg border border-line text-sm hover:border-primary"
    >
      <span aria-hidden="true">{ICON[choice]}</span>
    </button>
  );
}
